// Reaches `net`, which the lockfile records, and `env`, which it does not.
import { netAddress, tcpConnect } from "nish:net";

const dial = (port: i32): boolean => {
  const addr: u8[] = [];
  return netAddress(addr, "127.0.0.1", port) >= 0 && tcpConnect(addr) >= 0;
};

const config = (): i32 => {
  const v = getenv("NISH_CAPS_LOCK_UNGATED_NEVER_SET");
  return v === null ? 0 : v.length;
};

export const fetchText = (port: i32): i32 => (dial(port) ? config() : 2);
